INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('agaricus_arvensis', 'Печериця польова', 'Agaricus arvensis', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 8–20 см, спочатку напівсферична, потім опуклю- або плоско-розпростерта; біла, згодом кремова; гладенька або дрібнолуската; край спочатку підігнутий, потім розпростертий. • Пластинки: вільні, густі; спочатку рожеві, згодом темно-коричневі. • Ніжка: 6–10 × 1–2 см, циліндрична, біла, з двокільцевим кільцем; біля основи часто потовщена. • М’якоть: біла, на зламі не змінюється або злегка жовтіє; запах анісу або мигдалю; смак приємний. • Споровий порошок: темно-коричневий.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["white"], "stem": ["ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('agaricus_silvaticus', 'Печериця лісова', 'Agaricus silvaticus', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 см, опукла, згодом плоско-розпростерта; сірувато-бура, з бурими лусками; край підігнутий. • Пластинки: вільні, густі; білі → рожеві → темно-коричневі. • Ніжка: 5–10 × 0,8–1,5 см, циліндрична, білувата, з кільцем. • М’якоть: біла, на зламі червоніє; запах приємний, грибний. • Споровий порошок: темно-коричневий.', '{6,7,8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["ring"], "tree": ["coniferous", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('agaricus_xanthodermus', 'Печериця жовтошкіра', 'Agaricus xanthodermus', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 см, опукла, згодом плоско-розпростерта; біла, при дотику жовтіє; край підігнутий. • Пластинки: вільні, густі; рожеві → коричневі. • Ніжка: 6–12 × 1–2 см, біла, з кільцем; біля основи жовтіє. • М’якоть: біла, на зламі жовтіє; запах карболки або чорнила. • Споровий порошок: темно-коричневий.', '{6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('amanita_citrina', 'Мухомор цитриновий', 'Amanita citrina', 'poisonous', 'Отруйний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, напівсферична, згодом опуклю-розпростерта; лимонно-жовта, зеленувата, з білими пластівцями; край гладенький. • Пластинки: вільні, білі. • Ніжка: 6–10 × 1–1,5 см, біла, з кільцем і бульбою; біля основи піхва. • М’якоть: біла, із запахом редьки. • Споровий порошок: білий.', '{7,8,9,10}'::INT[], '{"color": ["yellow"], "stem": ["ring", "volva"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('amanita_porphyria', 'Мухомор пурпуровий', 'Amanita porphyria', 'poisonous', 'Отруйний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–8 см, напівсферична, згодом опуклю-розпростерта; сірувато-бура з пурпуровим відтінком, з білими пластівцями. • Пластинки: вільні, білі. • Ніжка: 6–10 × 0,8–1,2 см, біла, з кільцем; біля основи вільна біла піхва. • М’якоть: біла, без виразного запаху або з легким редьковим. • Споровий порошок: білий.', '{7,8,9}'::INT[], '{"color": ["brown", "grey", "purple"], "stem": ["ring", "volva"], "tree": ["birch", "coniferous", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('amanita_vittadinii', 'Мухомор Віттадіні', 'Amanita vittadinii', 'poisonous', 'Отруйний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–10 (20) см, напівсферична, згодом плоско-розпростерта; біла, кремова, з гострими конусовидними бородавками. • Пластинки: вільні, білі. • Ніжка: 5–8 (20) × 1–3 (4) см, біла, з подвійним кільцем; біля основи приросла піхва. • М’якоть: щільна, біла, з неприємним запахом. • Споровий порошок: білий.', '{6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["ring", "volva"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('amanita_echinocephala', 'Мухомор колючоголовий', 'Amanita echinocephala', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 6,5–14 см, опуклю-розпростерта; біла, в центрі вохряна, з пірамідальними гострими бородавками; край гладенький. • Пластинки: вільні, кремово-зеленуваті. • Ніжка: 10–15 × 1,3–4 см, біла, з кільцем і прирослою піхвою; внизу з лускатими зонами. • М’якоть: білувата або кремова, щільна, з приємним запахом. • Споровий порошок: білий.', '{6,7,8}'::INT[], '{"color": ["ochre", "white"], "stem": ["ring", "volva"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('boletus_calopus', 'Боровик неїстівний', 'Boletus calopus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 см, напівсферична, згодом подушковидно-розпростерта; сірувато-коричнева, жовтувато- або оливково-коричнева; суха, тонкоповстиста. • Трубочки/пори: пори зеленувато-жовті, при натиску синіють. • Ніжка: 5–10 (12) × 1,5–4 см, вгорі жовта, донизу червона, зі світлою сіткою. • М’якоть: білувата, згодом жовтувата, на зламі синіє; смак дуже гіркий. • Споровий порошок: вохряно-оливковий.', '{7,8,9}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["coniferous", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('boletus_impolitus', 'Боровик жовтий', 'Boletus impolitus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 (20) см, дуже м’ясиста; оливково-буро-коричнева; гладенька, з товстим краєм. • Трубочки/пори: пори жовтуваті, згодом зеленувато-жовті, при натиску зеленіють. • Ніжка: 5–15 (18) × 2–5 (8) см, без сітки, штрихувата, борошниста, дрібнолуската. • М’якоть: у шапці та ніжці жовтуватий, на зламі не змінюється; запах карболки; смак добрий. • Споровий порошок: оливковий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "olive"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "mixed", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('boletus_queletii', 'Боровик Келета', 'Boletus queletii', 'conditionally_edible', 'Умовно їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 (20) см, напівсферична, згодом подушковидно-розпростерта; оранжево- або коричнювато-червона; суха, тонкоповстиста. • Трубочки/пори: пори жовті → червоні; при дотику синіють. • Ніжка: 5–12 (15) × 2–4 (6) см, жовта, біля основи червона, зерниста. • М’якоть: жовта, на зламі синіє, далі зеленіє та жовтіє; смак добрий. • Споровий порошок: коричнево-оливковий.', '{6,7,8,9,10}'::INT[], '{"color": ["orange", "red"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('boletus_erythropus', 'Боровик зернистоногий', 'Boletus erythropus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 (20) см, напівсферична, згодом опукло- або плоско-розпростерта; бурувато- або темно-коричнева, іноді з вохряним або оранжевим відтінком; тонковолокнисто-повстиста, згодом майже гола; при натискуванні синіє. • Трубочки/пори: пори спочатку жовті, згодом оранжево-червоні, далі оливково-пурпурові; при дотику синіють. • Ніжка: 7–15 × 2–4 (6) см, щільна, жовто-червона, повстисто-зерниста; при дотику синіє. • М’якоть: дуже щільна, жовта, на зламі швидко синіє; запах приємний; смак добрий. • Споровий порошок: оливковий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "pine"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('boletus_purpureus', 'Боровик пурпуровий', 'Boletus purpureus', 'poisonous', 'Отруйний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 (20) см, товстом’ясиста, напівкуляста, подушковидна; сірувата, попеляста, оливкувато- або жовтувато-сіра, іноді вся або лише до краю рожевувата; при дотику синіє, згодом червоніє. • Трубочки/пори: пори жовті, згодом червоні, пурпурово-червоні. • Ніжка: 5–14 × 2–6 см, дуже щільна, жовто-червона, донизу червона, повстисто-зерниста, з червоною сіткою. • М’якоть: золотисто-жовтий, на зламі швидко дуже синіє; запах фруктово-спиртовий; смак добрий. • Споровий порошок: оливковий.', '{7,8,9}'::INT[], '{"color": ["grey", "olive"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gyroporus_castaneus', 'Гіропор каштановий', 'Gyroporus castaneus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 (10–12) см, опукло- або плоско-розпростерта; каштаново- або іржаво-коричнева; суха, тонкоповстиста. • Трубочки/пори: пори білі, згодом жовтуваті, округлі, малі. • Ніжка: 4–7 × 1–3 см, кольору шапки, донизу злегка потовщується, з ум’ятинами, тонкоповстиста, з порожниною та перегородками всередині. • М’якоть: білий, не синіє на зламі. • Споровий порошок: жовтуватий.', '{7,8,9}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": ["deciduous", "mixed", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gyroporus_cyanescens', 'Гіропор синіючий', 'Gyroporus cyanescens', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (15) см, суха, опукло-розпростерта; спочатку білувата, потім світло-жовта, вохряна, жовта, у старих коричнювата; тонковолокнисто- або волосисто-лускато-повстиста. • Трубочки/пори: пори білі, згодом жовтуваті, при дотику синіють, округлі, потім овальні. • Ніжка: 4–8 (12) × 2–4 см, донизу розширена, у верхній частині біла, нижче кольору шапки, спочатку щільна, з віком з порожниною та перегородками. • М’якоть: щільний, білий, на зламі швидко синіє. • Споровий порошок: жовтуватий.', '{7,8,9,10}'::INT[], '{"color": ["white", "yellow"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gyrodon_lividus', 'Гіродон сизуватий', 'Gyrodon lividus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 см, опукло- або плоско-розпростерта, іноді ввігнута; сірувато-лимонна або сірувато-золотисто-жовта, рудувато-коричнювата; тонкоповстисто-волокниста, суха, при змочуванні клейкувата. • Трубочки/пори: трубочки дуже короткі (1–5 мм), жовті, з віком оливково-коричневі; пори неправильнокутасті, видовжені, лимонно- або золотисто-жовті, згодом зеленувато- або жовто-оливкові, з нерівними зубчастими краями; при дотику синіють, потім буріють. • Ніжка: 3–12 × 0,5–2,5 см, кольору шапки або світліша, борошниста, з віком гола; при натискуванні набуває рожево-коричнюватого кольору. • М’якоть: щільний, не швидко загниває, жовтуватий, у ніжці темніший, на зламі швидко синіє; смак приємний; без особливого запаху. • Споровий порошок: жовтувато-буро-оливковий.', '{8,9,10}'::INT[], '{"color": ["grey", "yellow"], "stem": ["no_ring"], "tree": ["alder", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('boletinus_cavipes', 'Болетин порожньоногий', 'Boletinus cavipes', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 см, конусовидна, згодом конусовидно-розпростерта; золотисто-жовта, коричнювата, інколи з червонуватим відтінком; суха, повстисто-волокнисто-луската. • Трубочки/пори: трубочки короткі, до 1 см; пори нерівномірно видовжені, неправильнокутасті, розміщені майже радіальними рядами, жовтувато-зеленуваті або оливкуваті; гіменофор спускається на ніжку, не відділяється легко від тканини шапки. • Ніжка: 3–9 × 1–3 см, циліндрична, часто зігнута, волокнисто-луската, з кільцем, з порожниною. • М’якоть: жовтуватий, у ніжці біля основи буруватий; без особливого запаху. • Споровий порошок: жовтувато-оливкуватий.', '{8,9,10}'::INT[], '{"color": ["yellow"], "stem": ["ring"], "tree": ["coniferous", "larch", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tylopilus_felleus', 'Тилопіл жовчний', 'Tylopilus felleus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см, напівкуляста, згодом опукло- або подушковидно-розпростерта; бурувато- або оливкувато-коричнювата, іноді з легким червонуватим відтінком; тонковолокнисто-повстиста, з віком гола, суха, у вологу погоду клейкувата. • Трубочки/пори: пори спочатку білі, згодом рожевуваті, брудно- або бурувато-рожеві, іноді з лілуватим відтінком, у старих рожево-коричневі. • Ніжка: 5–10 (16) × 2–4 (5) см, жовтувато-коричнювата, з виразною темно-бурою або чорною сіткою. • М’якоть: дуже гіркий, білий, на зламі рожевіє; запах приємний. • Споровий порошок: рожевий, червонуватий, іноді з лілуватим відтінком.', '{6,7,8,9,10}'::INT[], '{"color": ["brown", "olive"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "mixed", "oak", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('porphyrellus_porphyrosporus', 'Порфірел пурпуровоспоровий', 'Porphyrellus porphyrosporus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (12) см, опукло-розпростерта; бурувато- або оливкувато-коричнева; волокнисто-бархатиста або тонкоповстиста. • Трубочки/пори: трубочки часом біля ніжки пластиковидно розділяються; пори округло-кутасті (0,5–1 мм), брудно-кремові, сіруваті, потім жовтувато-сірувато-коричневі, часом брудно-коричневі з оливковим відтінком. • Ніжка: 4–16 × 1–4 см, брудно-коричнева, борошнисто-бархатиста. • М’якоть: білий, білуватий, на зламі червоніє, згодом буріє (у старих екземплярів сіріє); запах неприємний. • Споровий порошок: темно-пурпурово-коричневий або коричнево-темно-червоний.', '{7,8,9,10}'::INT[], '{"color": [], "stem": [], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gomphidius_glutinosus', 'Мокруха клейка', 'Gomphidius glutinosus', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (14) см, опукло-розпростерта, з опущеним краєм; пурпурово- або фіолетово-сіра, сірувато-коричнева, рудувато-лілувато-коричнева, іноді дуже слизька; шкірка легко знімається. • Пластинки: спускаються на ніжку, товсті, спочатку білі, згодом темніють до чорних з білуватим краєм. • Ніжка: 5–10 × 1–2,5 см, до основи потоншується, біла, згодом коричнева, біля основи зовні та в середині жовта, з кільцевидними залишками покривала. • М’якоть: у шапці білуватий або рожевуватий, у ніжці біля основи жовтий; без особливого запаху. • Споровий порошок: чорний.', '{8,9,10}'::INT[], '{"color": ["grey", "purple"], "stem": ["ring"], "tree": ["coniferous", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gomphidius_roseus', 'Мокруха рожева', 'Gomphidius roseus', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–6 см, напівсферична, згодом опукло- або плоско-розпростерта, з підігнутим краєм; рожева або червона різних відтінків; слизька. • Пластинки: білі, з часом сіруваті й чорні. • Ніжка: 4–6 × 1–1,5 см, біла, донизу звужена, з товстим кільцевидним утворенням; біля основи м’ясо-червоно-коричнювата або чорнувата. • М’якоть: білий, на зламі рожевіє; із запахом. • Споровий порошок: чорний.', '{8,9}'::INT[], '{"color": ["pink", "red"], "stem": ["ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gomphidius_rutilus', 'Мокруха слизька', 'Gomphidius rutilus', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (15) см, опукло-, згодом плоско- або увігнуто-розпростерта, з горбочком у центрі, з опущеним краєм; пурпурово-коричнева, лілувато-пурпурова; слизька. • Пластинки: спускаються на ніжку, товсті, спочатку жовті, з віком коричневіють до темно-оливкувато-коричневих. • Ніжка: 3–10 × 0,1–1 см, щільна, донизу звужена, жовто- або червоно-коричнева, вгорі здебільшого сірозерниста. • М’якоть: у шапці жовтуватий, оранжево-жовтий, з червоним відтінком, у ніжці біля основи оранжево-жовтий; без особливого запаху. • Споровий порошок: оливково-чорний.', '{8,9}'::INT[], '{"color": ["brown", "purple"], "stem": ["no_ring"], "tree": ["coniferous", "larch", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('gomphidius_maculatus', 'Мокруха плямиста', 'Gomphidius maculatus', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2,5–5 см, напівсферична, згодом опукло-розпростерта з підігнутим краєм; слизька; біла, потім м’ясо-червоно-коричнева, місцями темніша до чорно-коричневої. • Пластинки: білі, згодом сірувато-бурі, при дотику червоніють, потім чорніють. • Ніжка: 10–15 × 1–1,5 см, донизу потоншується, щільна, біла, з часом рожевіє, далі червоніє, вгорі сірувато-зерниста, біля основи жовта, при дотику чорніє, без залишків покривала. • М’якоть: білий, на зламі рожевіє, згодом темніє, у ніжці біля основи коричневіє; без запаху. • Споровий порошок: чорний.', '{8,9}'::INT[], '{"color": ["red", "white"], "stem": ["no_ring"], "tree": ["larch"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('paxillus_atrotomentosus', 'Паксил чорноповстистий', 'Paxillus atrotomentosus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: до 15 см, дуже щільна, м’ясиста, опукло- або увігнуто-розпростерта, іноді майже лійковидна, часто ексцентрична; рудувато-коричнева, іноді з червонуватим відтінком; суха, з дуже закрученим товстим гладеньким краєм. • Пластинки: вохряно-жовті, низько спускаються на ніжку, з численними анастомозами. • Ніжка: 3–5 × 1,5–3,5 см, чорно-коричнева, повстиста, ексцентрична, щільна. • М’якоть: білуватий, гіркий, без особливого запаху. • Споровий порошок: вохряно-жовтий.', '{6,7,8,9,10}'::INT[], '{"color": ["brown", "russet"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('paxillus_panuoides', 'Паксил вохряно-рудий', 'Paxillus panuoides', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–8 (10) см, тонком’ясиста; жовтувата, вохряно-руда, коричнювата; тонкоповстиста, згодом гола; з тонким повстистим закрученим краєм. • Пластинки: оливково-жовті, оранжево-жовті, часто з перетинками. • Ніжка: дуже коротка, центральна, ексцентрична, бічна, іноді відсутня (шапка прикріплена боком до субстрату). • М’якоть: білий, без особливого запаху. • Споровий порошок: бурувато-жовтий.', '{7,8,9}'::INT[], '{"color": ["ochre", "yellow"], "stem": ["no_ring"], "tree": ["coniferous", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('ripartites_tricholoma', 'Рипартитес рядовковидний', 'Ripartites tricholoma', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–5 см, тонком’ясиста, плоско- або увігнуто-розпростерта; брудно- або сірувато-біла, згодом сірувато-, іноді іржаво-коричнева; гола, клейкувата, після висихання блискуча, іноді притиснуто-волокнисто-луската; з закрученим, потім рівним, тонким, торочкувато-волосистим краєм. • Пластинки: тонкі, вузькі, низько спускаються на ніжку, коричнюваті, легко відділяються від м’якуша шапки. • Ніжка: 2–4 × 0,3–0,5 см, білувата, вгорі борошнисто-луската, з порожниною. • М’якоть: білуватий, без особливого запаху. • Споровий порошок: бурувато-вохряний, світло-коричневий.', '{8,9}'::INT[], '{"color": ["grey", "white"], "stem": ["no_ring"], "tree": ["oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('ripartites_helomorpha', 'Рипартит геломорфний', 'Ripartites helomorpha', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2,5–6 см, тонком’ясиста, напівкуляста, згодом опукло-розпростерта з горбочком у центрі, іноді злегка увігнута; бурувато-жовтувата, в центрі темніша; з ребристим краєм. • Пластинки: низько спускаються на ніжку, кольору шапки. • Ніжка: 2–3 × 0,3–0,5 см, циліндрична, іноді зігнута, білувата, внизу коричнювата, щільна. • М’якоть: білуватий, без особливого запаху. • Споровий порошок: іржаво-коричнюватий.', '{8,9}'::INT[], '{"color": ["brown", "yellow"], "stem": ["no_ring"], "tree": ["coniferous", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_sanguifluus', 'Рижик червоний', 'Lactarius sanguifluus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–10 (15) см, опукло-, згодом увігнуто-розпростерта, часто з загнутим краєм; оранжево-руда, червонувато-руда, без концентричних зон; суха, блискуча. • Пластинки: спускаються на ніжку, густі, вузькі, оранжево-руді, при пошкодженні зеленіють. • Ніжка: 3–6,5 × 0,8–2,5 см, циліндрична, іноді до основи злегка звужена, щільна, з віком з вузькою порожниною, вгорі білувата, нижче кольору шапки, із зеленими плямами. • М’якоть: оранжево-рудий, на зламі зеленіє, з приємним фруктовим запахом; смак приємний. • Споровий порошок: жовтуватий. • Молочний сік: криваво-червоний, на повітрі не змінюється, спочатку солодкий, згодом гіркий.', '{8,9,10}'::INT[], '{"color": ["orange", "russet"], "stem": ["no_ring"], "tree": ["mixed", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_semisanguifluus', 'Хрящ-молочник зеленувато-червоний', 'Lactarius semisanguifluus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 (10) см, товстом’ясиста, щільна, увігнуто-розпростерта, лійковидна; брудно-оранжева, червонувато-оранжева, зеленувато-руда; гладенька, з легко знімною шкіркою; з закрученим краєм. • Пластинки: спускаються на ніжку, густі, вузькі, оранжеві, при пошкодженні зеленіють. • Ніжка: 3–8 × 1–2 см, циліндрична, щільна, з віком з порожниною, оранжева, при дотику зеленіє. • М’якоть: жовтуватий, під шкіркою шапки зеленуватий, солодкий, з приємним фруктовим запахом. • Споровий порошок: жовтуватий. • Молочний сік: оранжевий, на повітрі стає пурпуровим, згодом пурпурово-фіолетовим, потім коричнево-фіолетовим; спочатку солодкий, згодом гіркий.', '{7,8,9,10}'::INT[], '{"color": ["orange"], "stem": ["no_ring"], "tree": ["mixed", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_fuliginosus', 'Хрящ-молочник сірий', 'Lactarius fuliginosus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 (10) см, часто ексцентрична, тупоконусовидна, згодом опукло-, плоско- або увігнуто-розпростерта, з тонким плоским краєм; сірувато-кремова, сірувата, сірувато-рудувато-коричнювата; гола, суха, матова. • Пластинки: спочатку кольору шапки, з віком сірувато-вохряні, вохряно-жовті, запорошені спорами, при натискуванні червоніють. • Ніжка: 3–7 × 0,5–1,5 см, циліндрична або донизу потовщена, біла, з віком кольору шапки, щільна, при дотику червоніє. • М’якоть: білий, на зламі через кілька хвилин червоніє, злегка гіркуватий, з неприємним запахом. • Споровий порошок: світло-вохряний. • Молочний сік: білий, на повітрі червоніє, при відділенні від м’якуша не змінюється, солодкий або гіркуватий.', '{7,8,9,10}'::INT[], '{"color": ["grey", "white"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_acris', 'Хрящ-молочник червоніючий', 'Lactarius acris', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–7 (9) см, м’ясиста, розпростерта, з горбом або лійковидна, часом асиметрична; сірувато-руда, сірувато-каштанова, сіро-коричнева, з оливковим відтінком, з віком часто вицвітає до жовтуватої; з невиразними концентричними зонами. • Пластинки: спускаються на ніжку, густі, вузькі, кремові, при пошкодженні червоніють. • Ніжка: 4–7 × 0,8–1,5 см, циліндрична, щільна, біла або кольору шапки, при дотику червоніє. • М’якоть: білий, на зламі червоніє, злегка гіркуватий, з неприємним запахом. • Споровий порошок: світло-вохряний. • Молочний сік: білий, на повітрі червоніє, при відділенні від м’якуша не змінюється, пекуче-їдкий.', '{7,8,9,10}'::INT[], '{"color": ["grey", "russet"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_chrysorrheus', 'Хрящ-молочник золотисто-жовтий', 'Lactarius chrysorrheus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–9 см, опукло-розпростерта, згодом увігнуто-розпростерта, часто з невиразними концентричними зонами; вохряно-червонувато-оранжева, м’ясо-червона, з темнішими зонами; гола, гладенька, суха. • Пластинки: спускаються на ніжку, густі, вузькі, білуваті, згодом кремові, при пошкодженні жовтіють. • Ніжка: 3–6 × 0,8–1,5 см, циліндрична, щільна, з віком з порожниною, вгорі білувата, нижче кольору шапки. • М’якоть: білий, на зламі жовтіє, без особливого запаху; смак пекуче-їдкий. • Споровий порошок: світло-вохряний. • Молочний сік: білий, на повітрі швидко стає сірчано-жовтим, пекуче-їдкий.', '{7,8,9,10}'::INT[], '{"color": ["ochre", "orange", "red"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_theiogalus', 'Хрящ-молочник болотний', 'Lactarius theiogalus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2,5–5 (7) см, опукло-розпростерта, згодом увігнуто-розпростерта, з підігнутим краєм; м’ясо-цегляна, рудувато-оранжево-червонувата, рудувато-червонувато-коричнювата; гола, суха. • Пластинки: спускаються на ніжку, густі, вузькі, кремові, згодом вохряні, при пошкодженні жовтіють. • Ніжка: 3–6 × 0,4–1 см, циліндрична, щільна, з віком з порожниною, кольору шапки або світліша. • М’якоть: білуватий, на зламі жовтіє, неприємний на смак, без особливого запаху. • Споровий порошок: світло-вохряний. • Молочний сік: білий або водянисто-білий, на повітрі стає сірчано-жовтим; спочатку солодкуватий, згодом гіркий, далі пекуче-їдкий.', '{7,8,9,10}'::INT[], '{"color": ["red"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "deciduous", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_hepaticus', 'Хрящ-молочник оранжево-пластинчастий', 'Lactarius hepaticus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5,5 (7) см, увігнуто-розпростерта, часто з маленьким конусовидним виступом у центрі; червоно-коричнева, каштаново-коричнева, до краю світліша, з віком вицвітає до червонувато-жовто-коричневої; гола, суха. • Пластинки: спускаються на ніжку, густі, вузькі, червонувато-рудуваті, майже оранжеві, з віком рудувато-коричнюваті, часто припорошені споровою масою. • Ніжка: 3–5 (6) × 0,4–0,8 см, циліндрична, щільна, з віком з каналом, кольору шапки, біля основи волосиста. • М’якоть: світло-вохряний, у ніжці червонуватий, біля основи лілувато-червонуватий, на зламі стає сірчано-жовтим; пекуче-їдкий; з незначним приємним запахом. • Споровий порошок: світло-жовта. • Молочний сік: білий або водянисто-безбарвний, на повітрі стає темно-жовтим, пекуче-їдкий.', '{9,10}'::INT[], '{"color": ["brown", "red"], "stem": ["no_ring"], "tree": ["mixed", "pine"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_scrobiculatus', 'Хрящ-молочник жовтий', 'Lactarius scrobiculatus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 (20) см, товсто-щільно-м’ясиста, увігнуто-розпростерта, часом лійковидна; жовта, жовто-вохряна, при натискуванні коричневіє; слизька; з підігнутим шерстистим, згодом темно-волокнисто-плівчасто-лускатим краєм. • Пластинки: спускаються на ніжку, вузькі, густі, білуваті, жовтуваті з червонуватим відтінком. • Ніжка: 3–6 (8) × 1,5–3,5 см, коротша за діаметр шапки, кольору шапки або світліша, з ум’ятинами, щільна, згодом з порожниною. • М’якоть: білий, з віком жовтуватий, на зламі стає сірчано-жовтим; пекуче-їдкий; з приємним запахом. • Споровий порошок: світло-вохряний. • Молочний сік: білий, пекуче-їдкий, на повітрі стає сірчано-жовтим.', '{7,8,9}'::INT[], '{"color": ["yellow"], "stem": ["no_ring"], "tree": ["coniferous", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_trivialis', 'Хрящ-молочник сизий', 'Lactarius trivialis', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: (3) 5–15 (20) см, дуже щільном’ясиста, опукло- або увігнуто-розпростерта; спочатку лілувато-сиза, синювато-сіра, з віком сірувато-червонувато-рудувата або лілово-коричнювата; гола, слизька, при натискуванні коричневіє. • Пластинки: спускаються на ніжку, широкі, білуваті, згодом світло-вохряні. • Ніжка: 4–12 × 1–3,5 см, з порожниною, світло-вохряна або оранжева з м’ясо-червоним відтінком, слизька. • М’якоть: білуватий, під шкіркою лілувато-сірий або коричнюватий, у ніжці біля основи рудуватий, з легким запахом оселедця, на зламі злегка жовтіє. • Споровий порошок: жовтуватий. • Молочний сік: білий, на повітрі стає сірчано-жовтим, сухий сірувато-зелений, дуже пекуче-їдкий.', '{7,8,9,10}'::INT[], '{"color": ["grey", "purple"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "mixed", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_musteus', 'Хрящ-молочник моховий', 'Lactarius musteus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–8 (10) см, вохряно-сірувата, вохряно-сіра, з віком нерівномірно червонувато-сіра; часто асиметрична, опукло- або увігнуто-розпростерта, іноді лійковидна; з підігнутим, згодом опущеним, з віком короткорубчастим краєм; спочатку по краю тонковолосиста, потім гола, клейка, при підсиханні блискуча. • Пластинки: спускаються на ніжку, вузькі, густі, білуваті, згодом червонувато-жовтуваті, при натискуванні стають іржаво-коричневими. • Ніжка: 3–7 × 1,3–5 см, циліндрична, часто зігнута, щільна, з віком з порожниною, кольору шапки, зморшкувата. • М’якоть: білий, при натискуванні стає іржаво-коричнюватим, солодкий, з приємним фруктовим запахом. • Споровий порошок: жовтуватий. • Молочний сік: білий, на повітрі стає сірчано-жовтим, солодкий (після з’явлення швидко зникає).', '{8,9,10}'::INT[], '{"color": ["grey", "ochre"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_rubrocinctus', 'Хрящ-молочник рубчастий', 'Lactarius rubrocinctus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, увігнуто-розпростерта або лійковидна, з опущеним, груборубчастим краєм; червонувато-вохряна, червонувато-сіро-вохряна, червонувато-коричнева; гола або зерниста, шорстка, іноді дрібногорбкувата, при натискуванні стає пурпурово-коричневою. • Пластинки: спускаються на ніжку, густі, вузькі, кремові, з віком червонувато-вохряні. • Ніжка: 3–7 × 0,4–2 см, циліндрична, біля основи звужена, щільна, з віком з порожниною, кольору шапки, внизу темно-червона, волосиста. • М’якоть: світло-вохряний або червонувато-жовтуватий, у ніжці біля основи іржаво-коричневий або червонувато-темно-коричневий, з неприємним запахом; гіркий або пекуче-їдкий. • Споровий порошок: червонувата, світло-вохряна. • Молочний сік: білий, водянисто-білий, на повітрі коричневіє; спочатку солодкий, потім гіркий і пекуче-їдкий.', '{7,8,9,10}'::INT[], '{"color": ["ochre", "red"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "mixed", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_glaucescens', 'Хрящ-молочник зеленіючий', 'Lactarius glaucescens', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (15) см, щільном’ясиста, здебільшого асиметрична, увігнуто-розпростерта або лійковидна, з опущеним краєм; біла, кремова або нерівномірно біло-рудувата, з віком стає брудно-вохряно-рудувато-плямиста; суха, гола. • Пластинки: спускаються на ніжку, густі, вузькі, білі, з часом рожевувато-жовтуваті, на зламі сіро-зелено-плямисті. • Ніжка: 3–7 × 1–4 см, тонкозморшкувата, вгорі пухнаста, щільна, кольору шапки. • М’якоть: білий, щільний, із слабким приємним запахом; їдкий. • Споровий порошок: біла. • Молочний сік: білий, пекуче-їдкий, на повітрі, особливо при підсиханні, стає зеленувато-синюватим або сіро-зеленим.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_blennius', 'Хрящ-молочник сіро-зелений', 'Lactarius blennius', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–8 (10) см, зеленувато-сіра, темно-оливково- або зеленувато-сіро-коричнювата, в центрі іноді червонувато- або лілувато-сіро-коричнева; часто з вузькими темнішими концентричними смугами; гола, слизька; увігнуто-розпростерта, з підігнутим, потім опущеним, часом хвилястим краєм. • Пластинки: спускаються на ніжку, густі, вузькі, білі, згодом жовтуваті, з віком червонувато-жовтуваті або рудуваті, часто з сірувато-зеленуватими краплями підсохлого молочного соку. • Ніжка: 3–6 × 0,8–1,5 (2) см, циліндрична або донизу злегка звужена, нещільна, з порожниною, кольору шапки або світліша, клейка, при натискуванні сіріє або коричневіє. • М’якоть: білуватий, з віком сіруватий, пекуче-їдкий, без особливого запаху. • Споровий порошок: жовтуватий. • Молочний сік: білий, на повітрі (разом з м’якушем) стає сірим або зеленувато-сірим, при відділенні від м’якуша не змінюється, пекуче-їдкий.', '{7,8,9,10}'::INT[], '{"color": ["green", "grey"], "stem": ["no_ring"], "tree": ["beech", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_vietus', 'Хрящ-молочник бляклий', 'Lactarius vietus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2,5–7 (10) см, лілувато-сіро-коричнювата або лілувато-сіра, до краю світліша, часто з невиразними зонами; слизька, клейка, при підсиханні блискуча; у центрі іноді зморшкувата, тупоконусовидна, згодом плоско- або увігнуто-розпростерта, іноді з маленьким конусовидним виступом, часом лійковидна; з підігнутим, потім плоским тонким краєм. • Пластинки: кремуваті, згодом сірувато-жовтуваті, з червонуватим відтінком, при дотику сіро-оливково-коричневі. • Ніжка: 3–6 (8) × 0,4–1,5 см, щільна, з віком часто з порожниною, білувата або світло-лілувато-сірувата, іноді вохряно-сірувата, суха. • М’якоть: білуватий, під шкіркою темніший, їдкуватий, без особливого запаху, на зламі сіріє. • Споровий порошок: жовтуватий. • Молочний сік: білий, на повітрі стає оливково- або зелено-сірим; спочатку солодкий, потім пекучий.', '{9,10}'::INT[], '{"color": ["grey", "purple"], "stem": ["no_ring"], "tree": ["birch", "mixed"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_uvidus', 'Хрящ-молочник ліловіючий', 'Lactarius uvidus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, фіолетово-сіра, м’ясо-сіра, сірувато-лілувато-коричнювата, з невиразними темнішими зонами; опукло- або плоско-розпростерта, іноді з горбочком, часто увігнута до лійковидної; гола, слизька, при підсиханні блискуча. • Пластинки: спускаються на ніжку, вузькі, білі, згодом жовтуваті; при дотику ліловіють або синіють. • Ніжка: 5–12 × 0,5–2 см, спочатку щільна, з віком з порожниною; білувата, потім світло-лілувато-сірувата, біля основи повстисто-волокниста, жовтувата, клейкувата; при дотику ліловіє. • М’якоть: білий, у ніжці внизу жовтуватий; гіркуватий. • Споровий порошок: жовтуватий. • Молочний сік: білий, на повітрі ліловіє, при відділенні від м’якуша не змінюється; гіркий.', '{8,9,10}'::INT[], '{"color": ["grey", "purple"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "deciduous", "willow"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_violascens', 'Хрящ-молочник фіолетовий', 'Lactarius violascens', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (15) см, фіолетово-коричнева, з кількома темнішими концентричними зонами; увігнуто-розпростерта; при натискуванні темніє. • Пластинки: жовтуваті, згодом коричнюваті, з вохряним відтінком; при натискуванні повільно стають червоно-фіолетовими, далі фіолетово-коричневими. • Ніжка: (2–3) 4–6 × 1–2,5 см, щільна, з часом з порожниною; вохряно-коричнювата, вгорі борошниста, біля основи волокниста; при натискуванні червонувато-фіолетова. • М’якоть: щільний, жовтувато- або коричнювато-білуватий, гіркуватий, на зламі в ніжці та над пластинками червонувато-фіолетовий; із приємним запахом. • Споровий порошок: жовтуватий. • Молочний сік: водянисто-білий або білий, на повітрі ліловіє, гіркуватий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "purple"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_aspideus', 'Хрящ-молочник жовтуватий ліловіючий', 'Lactarius aspideus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–5 (9) см, білувато-жовта, іноді лимонно-жовта, до краю світліша; опукло- або плоско-розпростерта, з віком увігнуто-розпростерта; гола, суха, при зволоженні клейка або слизиста; при натискуванні лілово-сіра до коричнево-фіолетової. • Пластинки: білі, з віком жовтуваті, з сірувато-червонуватим відтінком; вузькі, спускаються на ніжку; при дотику ліловіють, далі стають лілово-сірими, коричнюватими. • Ніжка: 3–8 × 0,5–1,5 см, циліндрична або до основи розширена, щільна; вгорі білувата, донизу жовтувата, біля основи іноді руда; при дотику ліловіє, потім стає лілово-сірою. • М’якоть: білий, з приємним запахом, на зламі швидко ліловіє, потім повільно знебарвлюється; спочатку солодкий, згодом пекуче-гіркий. • Споровий порошок: жовта. • Молочний сік: білий, спочатку у великій кількості, згодом майже зникає; на повітрі повільно ліловіє; мінливого смаку: спочатку солодкий, потім гіркий, далі пекучий.', '{7,8,9}'::INT[], '{"color": ["white", "yellow"], "stem": ["no_ring"], "tree": ["deciduous", "willow"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_repraesentaneus', 'Хрящ-молочник золотисто-жовтий ліловіючий', 'Lactarius repraesentaneus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (15) см, яскраво-жовта, золотисто-жовта; щільном’ясиста, подушковидно-опукла, згодом опукло-розпростерта, часто в центрі увігнута, з горбочком; притиснуто-волокниста, в центрі майже гола; з підігнутим, потім опущеним, пластівчасто- або волокнисто-лускатим, волохатим краєм; при зволоженні слизька, при підсиханні блискуча; від натискування ліловіє. • Пластинки: вузькі, густі, жовтуваті, згодом рожевувато-жовті, з бурувато-лілуватими плямами. • Ніжка: 4,5–8 (10) × 1–2,5 (3) см, здебільшого коротша за діаметр шапки; щільна, згодом з порожниною; кольору шапки або світліша; при зволоженні клейка, потім суха; при натискуванні ліловіє. • М’якоть: щільний, жовтуватий, на зламі стає нерівномірно розпливчасто-ліловим; із сильним приємним запахом; без особливого смаку або гіркуватий. • Споровий порошок: жовта. • Молочний сік: білий або водянисто-безбарвний, гіркуватий, на повітрі (разом з м’якушем) ліловіє, при відділенні не змінюється.', '{7,8,9,10}'::INT[], '{"color": ["yellow"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "mixed", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_pubescens', 'Хрящ-молочник пухнастий', 'Lactarius pubescens', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–9 см, волохата, волокнисто-пластівчаста, з віком здебільшого майже гола; тонком’ясиста, увігнуто-розпростерта; із закрученим пластівчасто-волосистим волохатим краєм; біла або кремова, у центрі темніша — до вохряної, рожевувато-вохряної; клейка. • Пластинки: вузькі, білуваті, згодом рожевувато-кремові. • Ніжка: (1) 2–5 × 1–1,5 см, дуже коротка, вгорі білувата, донизу рудувата або рожевувато-рудувата, з порожниною. • М’якоть: щільний, білий, пекуче-їдкий. • Споровий порошок: рожевувато-кремова. • Молочний сік: білий, пекуче-їдкий, на повітрі не змінюється.', '{9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["birch"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_controversus', 'Хрящ-молочник осиковий', 'Lactarius controversus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 (20) см, товсто-щільном’ясиста, спочатку подушковидно-опукла, згодом увігнуто-розпростерта; спочатку з закрученим повстистим, потім опущеним голим краєм; світло-кремова, з розпливчастими рожевими або червонуватими плямами, іноді вся брудно-рожевувата; гола, клейкувата, часто по краю з водянистими концентричними зонами. • Пластинки: кремуваті з рожевим відтінком, з віком брудно-рожевуваті, брудно-червонуваті; густі, вузькі. • Ніжка: 2–5 × 1,5–4 (5) см, значно коротша за діаметр шапки, щільна, кольору шапки. • М’якоть: дуже щільний, білуватий, з віком у шапці рожевуватий, у ніжці жовтий; на зламі не змінюється; пекуче-їдкий; із приємним запахом. • Споровий порошок: рожевувата. • Молочний сік: білий, їдкий або гіркий; у молодих плодових тіл не дуже їдкий; на повітрі не змінюється.', '{8,9,10,11}'::INT[], '{"color": ["pink", "white"], "stem": ["no_ring"], "tree": ["aspen", "deciduous", "mixed", "poplar", "willow"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_turpis', 'Хрящ-молочник оливково-чорний', 'Lactarius turpis', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (20) см, оливково-коричнева, оливково-бура, іноді оливково-чорнувата, до краю світліша, жовтувата; з б.-м. яскравими темнішими концентричними зонами; гола, клейка; щільном’ясиста, увігнуто-розпростерта, з підігнутим, потім опущеним краєм. • Пластинки: вузькі, білуваті або жовтуваті, згодом брудно-жовті до коричнюватих; стиглі при дотику коричневіють або буріють. • Ніжка: 3–6 (8) × 1–2,5 см, щільна, кольору шапки або світліша, ямчаста, клейка. • М’якоть: білий, на зламі темніє; їдкуватий; із слабким грибним запахом. • Споровий порошок: кремова. • Молочний сік: білий або водянисто-безбарвний, на повітрі не змінюється, пекуче-їдкий.', '{7,8,9,10,11}'::INT[], '{"color": ["brown", "olive"], "stem": ["no_ring"], "tree": ["birch", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_mammosus', 'Хрящ-молочник сосочковий', 'Lactarius mammosus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–6 (9) см, сіро-коричнева, темно-коричнева, темно-сіро-бура, чорно-коричнювата, іноді з легким фіолетовим відтінком, до краю світліша; суха, волокнисто-повстиста або волокнисто-луската; тонком’ясиста, плоско-розпростерта, згодом часом увігнуто-розпростерта, часто з горбочком у центрі. • Пластинки: густі, вузькі, жовті, з часом червонувато-рудуваті; при натискуванні коричневіють. • Ніжка: 3–5 (7) × 0,8–2 см, циліндрична, щільна, згодом з каналом; білувата, з віком кольору шапки; при натискуванні стає буро-вохряною. • М’якоть: у шапці білуватий, під шкіркою темний, у ніжці червонувато-рудуватий; щільний, солодкуватий; у свіжих плодових тіл без запаху, у підсихаючих — з ароматним приємним запахом. • Споровий порошок: кремова. • Молочний сік: білий, на повітрі не змінюється; спочатку солодкуватий, згодом гострий або гіркий; у старих плодових тіл майже відсутній.', '{8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_flexuosus', 'Хрящ-молочник сіро-лілуватий', 'Lactarius flexuosus', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 (15) см, брудно-лілово-сіра, коричнювато-лілово-сіра, з темнішими концентричними смугами, іноді без смуг; товсто-щільном’ясиста, опукло- або увігнуто-розпростерта, іноді лійковидна, часто асиметрична; з підігнутим, згодом опущеним хвилястим або лопатевидним краєм; суха, при зволоженні клейкувата; при натискуванні темніє. • Пластинки: товсті, рідкі, з проміжними жилками, кремові, з віком червонувато-світло-вохряні. • Ніжка: 3–8 × 1,5–3,5 см, донизу звужується; вгорі білувата, донизу кольору шапки; щільна; при натискуванні темніє. • М’якоть: жовтувато-білуватий, під шкіркою лілувато-коричнюватий; пекуче-їдкий, при підсиханні гіркуватий; із приємним запахом. • Споровий порошок: кремова. • Молочний сік: білий (засихаючий кремовий), дуже пекуче-їдкий.', '{7,8,9}'::INT[], '{"color": ["grey", "purple"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "deciduous", "mixed", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lactarius_spinosulus', 'Хрящ-молочник шипастий', 'Lactarius spinosulus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1,5–4,5 (6) см, лілувато-сіро-рожева, лілувато-сіро-червонувата; радіальноволокниста, стовбурчастолуската; тонком’ясиста, опукло- або плоско-розпростерта, іноді майже лійковидна, здебільшого з гострим горбочком у центрі, з опущеним тонким краєм; клейка; при натискуванні зеленіє. • Пластинки: тонкі, густі, з віком рідкі, вузькі, світло-вохряні, далі червонувато-вохряні, припорошені споровою масою; при натискуванні стають коричнево-зеленуватими. • Ніжка: 2–5 × 0,3–0,8 см, донизу звужена, щільна або з каналом; кольору шапки, біля основи часом рудувата. • М’якоть: нерівномірно жовтувато-білуватий; спочатку солодкуватий, згодом (швидко) гоструватий; без особливого запаху; при натискуванні стає темно-зеленим. • Споровий порошок: рожевувато-світло-вохряна. • Молочний сік: білий, солодкуватий, згодом пекуче-їдкуватий.', '{8,9}'::INT[], '{"color": ["grey", "pink", "purple"], "stem": ["no_ring"], "tree": ["alder", "birch", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
