INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_album', 'Рядовка біла', 'Tricholoma album', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см, біла або кремова, гола, суха; опукла, згодом плоско-розпростерта, з підігнутим краєм. • Пластинки: білі, густі, прирослі. • Ніжка: 5–10 × 1–2 см, біла, волокниста, щільна. • М''якоть: біла, з неприємним запахом, пекучо-гірка. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_sulphureum', 'Рядовка сірчано-жовта', 'Tricholoma sulphureum', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 см, сірчано-жовта або оливкувато-жовта, шовковиста; опукла, згодом плоско-розпростерта. • Пластинки: жовті, густі, прирослі. • Ніжка: 5–10 × 1–1,5 см, жовта, волокниста. • М''якоть: жовта, з дуже неприємним запахом (сірководню або газу). • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["yellow"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_virgatum', 'Рядовка волокниста', 'Tricholoma virgatum', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–9 см, сіра або лілувато-сіра, радіально-чорноволокниста; опукла, згодом плоско-розпростерта, з горбочком. • Пластинки: білі, з часом сірі, густі. • Ніжка: 6–12 × 0,8–2,2 см, біла, сірувата, волокниста. • М''якоть: сірувата, дуже гірка, з неприємним запахом. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["black", "grey"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_vaccinum', 'Рядовка рудувато-червона', 'Tricholoma vaccinum', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–7 см, червоно- або рудо-коричнева, шерстисто-повстисто-луската; опукла, згодом плоско-розпростерта, з горбочком. • Пластинки: білуваті, згодом брудно-червонуваті, густі. • Ніжка: 4–10 × 1–1,5 см, кольору шапки, волокнисто-луската. • М''якоть: біла, з запахом борошна. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "red"], "stem": ["no_ring"], "tree": ["coniferous", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_imbricatum', 'Рядовка черепичаста', 'Tricholoma imbricatum', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, рудувато- або буро-коричнева, волокнисто-луската (луски розташовані як черепиця); опукла, згодом плоско-розпростерта, з горбочком. • Пластинки: білуваті, згодом червонувато-коричнюваті, густі. • Ніжка: 7–13 × 1–2,5 см, білувата, волокниста. • М''якоть: білувата, з запахом борошна. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "russet"], "stem": ["no_ring"], "tree": ["coniferous", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_pessundatum', 'Рядовка згубна', 'Tricholoma pessundatum', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–15 см, руда або бурувато-жовтувата, волокнисто-луската; опукла, згодом плоско-розпростерта, часто з горбочком. • Пластинки: білі, згодом руді, густі. • Ніжка: 4–12 × 2–4 см, білувата, біля основи коричнювата. • М''якоть: біла, з запахом борошна, на зламі рудіє. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["russet"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_populinum', 'Рядовка тополева', 'Tricholoma populinum', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–15 см, коричнювата або сіро-коричнювата, волокнисто-луската; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом рудіють, густі. • Ніжка: 3–10 × 2–4 см, білувата, щільна. • М''якоть: біла, з запахом борошна, на зламі рудіє. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": ["aspen", "poplar"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_saponaceum', 'Рядовка сіра', 'Tricholoma saponaceum', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, сірувата або оливкувато-сірувата, гола; опукла, згодом плоско-розпростерта, часто з горбочком. • Пластинки: жовтувато- або зеленувато-білі, густі. • Ніжка: 5–12 × 1–3 см, біла або темно-сіра, волокнисто-луската. • М''якоть: гіркувата, з запахом мила (характерна ознака!). • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["grey"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_sejunctum', 'Рядовка відокремлена', 'Tricholoma sejunctum', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–10 см, зеленкувато- або оливкувато-жовта, в центрі коричнева, радіально-темноволокниста; опукла, згодом плоско-розпростерта, з горбочком. • Пластинки: білі, згодом жовтуваті, густі. • Ніжка: 5–12 × 1–3 см, біла, жовтувата, волокниста. • М''якоть: біла, гіркувата, з запахом борошна. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["green", "yellow"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('tricholoma_orirubens', 'Рядовка червоніюча', 'Tricholoma orirubens', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 см, сіра, в центрі темніша, чорноволокнисто-луската; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом рожевуваті, густі. • Ніжка: 5–8 × 1–2,5 см, біла, біля основи зеленкувата. • М''якоть: білувата, на зламі рожевіє. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["black", "grey"], "stem": ["no_ring"], "tree": ["oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_nebularis', 'Говорушка сіра', 'Clitocybe nebularis', 'conditionally_edible', 'Умовно їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 7–30 см, біла, сірувата або сіра, гола; опукла, згодом плоско-розпростерта, з горбочком, край підігнутий. • Пластинки: білуваті, згодом брудно-жовтуваті, густі, злегка спускаються на ніжку. • Ніжка: 5–12 × 2–4 см, білувата, волокниста, щільна, з віком з порожниною. • М''якоть: біла, з сильним фруктовим запахом. • Споровий порошок: кремовий.', '{9,10,11}'::INT[], '{"color": ["grey", "white"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_geotropa', 'Говорушка руда', 'Clitocybe geotropa', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–20 (30–40) см, брудно-жовтувата або коричнювата, увігнуто-розпростерта, з горбочком, згодом лійковидна; край закручений. • Пластинки: білуваті, згодом кольору шапки, низько спускаються на ніжку. • Ніжка: 5–16 × 1–4 см, білувата, щільна, згодом коркувата. • М''якоть: біла, щільна, з приємним запахом. • Споровий порошок: білий.', '{8,9,10,11}'::INT[], '{"color": ["brown", "yellow"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_gigantea', 'Говорушка гігантська', 'Clitocybe gigantea', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 10–40 см, біла, в центрі жовтувата, гола; опукла, згодом лійковидна, з закрученим краєм. • Пластинки: білі, з часом кольору шапки, густі, злегка спускаються. • Ніжка: 4–7 × 2–5 см, біла, борошниста, щільна. • М''якоть: біла, з легким запахом борошна; смак спочатку добрий, згодом гіркуватий. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_odora', 'Говорушка ароматна', 'Clitocybe odora', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–9 см, зелена або синювато-зелена, гола; опукла, згодом плоско-розпростерта. • Пластинки: зеленуваті, густі, прирослі. • Ніжка: 4–7 × 0,5–1 см, зеленувата, щільна. • М''якоть: білувата, з сильним запахом анісу. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["green"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_clavipes', 'Говорушка булавовиднонога', 'Clitocybe clavipes', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, сірувато-коричнева, гола; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом жовтуваті, густі. • Ніжка: 3–6 × 1–2 см, донизу булавовидно потовщена, сірувата. • М''якоть: біла, з слабким запахом. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_infundibuliformis', 'Говорушка лійковидна', 'Clitocybe infundibuliformis', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–15 см, рудувато-кремова або вохряно-жовта, лійковидна, з тонким хвилястим краєм. • Пластинки: білуваті, згодом кольору шапки, низько спускаються. • Ніжка: 3–6 × 0,5–1,2 см, біла, гола, щільна. • М''якоть: біла, з приємним запахом. • Споровий порошок: білий.', '{7,8,9,10}'::INT[], '{"color": ["red", "white"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_rivulosa', 'Говорушка червонувата', 'Clitocybe rivulosa', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–7 см, біла, з кремовими або рудуватими зонами, при зволоженні рудувато-м''ясо-червона; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом жовтуваті, густі. • Ніжка: 2–6 × 0,4–0,9 см, кольору шапки, щільна. • М''якоть: біла, з слабким приємним запахом. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": [], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_phyllophila', 'Говорушка листолюбна', 'Clitocybe phyllophila', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–11 см, біла або жовтувато-біла, шовковиста; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом кремово-жовтуваті, густі. • Ніжка: 2,5–8 × 0,3–1,2 см, кольору шапки, біля основи повстисто-волосиста. • М''якоть: біла, з сильним запахом борошна. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["beech", "deciduous"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_suaveolens', 'Говорушка запашна', 'Clitocybe suaveolens', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6 см, білувата, кремова, жовтувата, з рожевим відтінком; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом сірі, густі. • Ніжка: 3–6 × 0,3–0,6 см, кольору шапки, щільна. • М''якоть: біла, з приємним анісовим запахом. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["pink", "white"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('clitocybe_brumalis', 'Говорушка зимова', 'Clitocybe brumalis', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–7 см, сіра, жовто-сіра або сіро-коричнювата, увігнута, з горбочком; край підігнутий. • Пластинки: білуваті, згодом жовтуваті, густі. • Ніжка: 3–6 × 0,3–0,5 см, кольору шапки, білоповстиста. • М''якоть: біла, з запахом борошна. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["grey"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('collybia_dryophila', 'Колібія лісолюбна', 'Collybia dryophila', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6 см, білувата, рудувато-вохряна, жовтувато-коричнювата; опукла, згодом плоско-розпростерта, гола. • Пластинки: білуваті, згодом кремові, густі, прирослі. • Ніжка: 3–7 × 0,2–0,5 см, білувата, вохряно-жовтувата, волокниста, щільна. • М''якоть: біла, без особливого запаху. • Споровий порошок: білий.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["brown", "white", "yellow"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('collybia_peronata', 'Колібія обгорнута', 'Collybia peronata', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–7 см, бурувато-рудувата, вохряно-бурувата, зморшкувато-рубчаста; опукла, згодом плоско-розпростерта. • Пластинки: рідкі, коричнювато-жовті, прирослі. • Ніжка: 3–8 × 0,3–0,8 см, бурувато-коричнювата, повстиста, щільна. • М''якоть: жовтувата, пекучо-гірка. • Споровий порошок: білий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "russet"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('collybia_confluens', 'Колібія численна', 'Collybia confluens', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 см, бурувато-білувата, рожевувато-сірувато-жовта; опукла, згодом плоско-розпростерта. • Пластинки: густі, білуваті, згодом кольору шапки, прирослі. • Ніжка: 5–9 × 0,2–0,4 см, рудувата, повстисто-волосиста, щільна; ніжки зростаються у щільні групи. • М''якоть: білувата, без запаху. • Споровий порошок: білий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "white"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('collybia_maculata', 'Колібія плямиста', 'Collybia maculata', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см, біла, білувата, з рудуватими плямами; опукла, згодом плоско-розпростерта. • Пластинки: білі, густі, прирослі. • Ніжка: 6–10 × 1–2 см, біла, з плямами, борозенчаста, щільна. • М''якоть: біла, гірка. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["russet", "white"], "stem": ["no_ring"], "tree": ["coniferous", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('collybia_butyracea', 'Колібія рудувато-сіра', 'Collybia butyracea', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–9 см, рудувато-сірувата, сірувато-бурувата, гола; опукла, згодом плоско-розпростерта. • Пластинки: білуваті, густі, прирослі. • Ніжка: 4–8 × 0,5–2 см, білувата, штрихувата, щільна. • М''якоть: білувата, з приємним маслянистим запахом. • Споровий порошок: білий.', '{7,8,9,10,11}'::INT[], '{"color": ["grey", "russet"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('collybia_fusipes', 'Колібія веретенонога', 'Collybia fusipes', 'conditionally_edible', 'Умовно їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см, червонувато-коричнева, рудувато-коричнева, гола; опукла, згодом плоско-розпростерта. • Пластинки: білі, згодом рудуваті, густі, прирослі. • Ніжка: 8–12 × 1–2 см, веретеновидна, з кореневидним виростом, кольору шапки, щільна. • М''якоть: білувата, без запаху. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "red"], "stem": ["no_ring"], "tree": ["deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_pura', 'Міцена чиста', 'Mycena pura', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6,5 см, лілувата, рожева, жовтувато-рожева, гола, рубчаста; дзвониковидна, згодом плоско-розпростерта. • Пластинки: лілуваті, широкі, прирослі. • Ніжка: 4–7 × 0,2–1 см, кольору шапки, щільна. • М''якоть: з запахом редьки. • Споровий порошок: білий.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["pink", "purple"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_galericulata', 'Міцена ковпаковидна', 'Mycena galericulata', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6 см, сіра, коричнево-сіра, бурувато-коричнювата, гола; дзвониковидна, згодом плоско-розпростерта. • Пластинки: білуваті, згодом рожевуваті, густі, прирослі. • Ніжка: 2–11 × 0,15–0,7 см, кольору шапки, щільна. • М''якоть: з запахом борошна. • Споровий порошок: білий.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_polygramma', 'Міцена штрихувата', 'Mycena polygramma', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–4 см, бурувато- або коричнювато-сіра, штрихувата; дзвониковидна, згодом плоско-розпростерта. • Пластинки: білуваті, згодом рожевуваті, густі. • Ніжка: 3–14 × 0,1–0,5 см, зморшкувато-рубчаста, білувата, щільна. • М''якоть: без запаху. • Споровий порошок: білий.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_haematopus', 'Міцена кривавонога', 'Mycena haematopus', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–3 см, сіро-коричнево-рожева, пурпурово-коричнювата; дзвониковидна. • Пластинки: рідкі, білі. • Ніжка: 2–8 × 0,1–0,3 см, донизу криваво-червона, при пошкодженні виділяє червоний сік. • М''якоть: без особливого запаху. • Споровий порошок: білий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["brown", "grey", "pink"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_rosella', 'Міцена рожева', 'Mycena rosella', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 0,5–1,5 см у діаметрі; спочатку дзвоникоподібна, потім опукла або плоско-розпростерта; жовтувато-рожева, рожева, до краю червонувата; поверхня гладенька, злегка рубчаста; край рівний, тонкий, іноді хвилястий. • Пластинки: рожевуваті, з віком бліднішають; прирослі, досить густі. • Ніжка: 2,5–4 см × 0,1 см; циліндрична, кольору шапки або світліша; гладенька, порожниста; без кільця та піхви. • М’якоть: тонка, білувато-рожева; на зламі не змінюється; без виразного запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["pink"], "stem": ["no_ring"], "tree": ["coniferous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_epipterygia', 'Міцена слизька', 'Mycena epipterygia', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–2,5 см у діаметрі; дзвоникоподібна, потім опукла або плоско-розпростерта; сірувато-коричнева, жовтувата, іноді з оливковим відтінком; поверхня дуже клейка, рубчаста; край тонкий, рубчастий. • Пластинки: білі, згодом сіруваті; прирослі, густі. • Ніжка: 5–8 см × 0,1–0,17 см; циліндрична, лимонно-жовта; клейка, гладенька, порожниста; без кільця та піхви. • М’якоть: тонка, білувата; на зламі не змінюється; з неприємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "grey", "yellow"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_inclinata', 'Міцена нахилена', 'Mycena inclinata', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2,5–4 см у діаметрі; дзвоникоподібна, згодом опукла або плоско-розпростерта; брудно-біла, чорнувата, сіро-коричнева, з радіальними штрихами; поверхня гладенька, злегка рубчаста; край нерівний. • Пластинки: білуваті, згодом рожевуваті; прирослі, густі. • Ніжка: 4–9 см; циліндрична, часто нахилена; жовта, біля основи червоно-коричнева; гладенька, порожниста; без кільця та піхви. • М’якоть: тонка, білувата; на зламі не змінюється; з неприємним запахом; смак м’який. • Споровий порошок: білий.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["brown", "grey", "white"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_aetites', 'Міцена лужна', 'Mycena aetites', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–5 см у діаметрі; спочатку дзвоникоподібна, потім опукла або плоско-розпростерта; бурувато-коричнювато-сіра, коричнева, з радіальними рубчиками; поверхня гладенька, суха; край рубчастий. • Пластинки: сіро-коричневі; прирослі, густі. • Ніжка: 5–7 см × 0,2 см; циліндрична, кольору шапки; гладенька, порожниста; без кільця та піхви. • М’якоть: тонка, білувата; на зламі не змінюється; з дуже сильним аміачним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["coniferous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_galopus', 'Міцена білосокова', 'Mycena galopus', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–3 см у діаметрі; дзвоникоподібна, згодом опукла або плоско-розпростерта; коричнювата, сірувато-коричнева; поверхня гладенька, злегка рубчаста; край рівний. • Пластинки: білуваті; прирослі, густі. • Ніжка: 4–8 см × 0,1–0,15 см; циліндрична, коричнювата; при пошкодженні виділяє білий молочний сік; гладенька, порожниста; без кільця та піхви. • М’якоть: тонка, білувата; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('mycena_sanguinolenta', 'Міцена кривавоплямиста', 'Mycena sanguinolenta', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 0,6–2 см у діаметрі; дзвоникоподібна, згодом опукла або плоско-розпростерта; коричнювато-червона, червонувато-коричнева; поверхня гладенька, злегка рубчаста; край рівний. • Пластинки: білуваті; прирослі, густі. • Ніжка: 4–8 см × 0,1–0,15 см; циліндрична, коричнювато-червона; при пошкодженні виділяє коричнювато-червоний сік; гладенька, порожниста; без кільця та піхви. • М’якоть: тонка, білувата; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["brown", "red"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('marasmius_oreades', 'Опеньок луговий', 'Marasmius oreades', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 см у діаметрі; спочатку дзвоникоподібна, потім опукла або плоско-розпростерта, часто з горбочком; кремова, кольору шкіри, вохряно-кремова; поверхня гладенька, суха, матова; край рівний, іноді хвилястий. • Пластинки: білі, згодом кремові; рідкі, широкі; прирослі або майже вільні. • Ніжка: 4–7 см × 0,3–0,5 см; циліндрична, білувата; щільна, волокниста; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з приємним грибним запахом; смак приємний. • Споровий порошок: білий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('marasmius_alliaceus', 'Часничник великий', 'Marasmius alliaceus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 см у діаметрі; спочатку дзвоникоподібна, потім опукла або плоско-розпростерта; біла, білувата, згодом коричнювато-кремова; поверхня гладенька, суха; край рівний. • Пластинки: білуваті; прирослі, густі. • Ніжка: 4,5–20 см × 0,1–0,3 см; циліндрична, дуже довга; темна, майже чорна; гладенька, волокниста, щільна; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з дуже сильним запахом часнику; смак грибний. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('marasmius_scorodonius', 'Часничник дрібний', 'Marasmius scorodonius', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–3,5 см у діаметрі; спочатку дзвоникоподібна, потім опукла або плоско-розпростерта; червонувато-коричнювата, з віком вицвітає до світло-коричневої; поверхня гладенька, суха; край рівний, тонкий. • Пластинки: білі, червонувато-білі; прирослі, густі. • Ніжка: 2–4 см × 0,1–0,2 см; циліндрична, червонувато-темно-коричнева; гладенька, щільна; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з дуже сильним запахом часнику; смак грибний. • Споровий порошок: білий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "red"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('marasmius_prasiosmus', 'Маразмій вицвітаючий', 'Marasmius prasiosmus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–4 см у діаметрі; спочатку дзвоникоподібна, потім опукла або плоско-розпростерта; жовтувата, вохряно-бура, коричнювата, до краю світліша; поверхня гладенька, суха; край рівний, тонкий. • Пластинки: брудно-жовтуваті; прирослі, густі. • Ніжка: 2–6 см × 0,15–0,4 см; циліндрична, рудувата, коричнева; гладенька, щільна; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з дуже сильним запахом часнику; смак грибний. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "yellow"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('marasmius_rotula', 'Маразмій колесовидний', 'Marasmius rotula', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 0,5–1,5 см у діаметрі; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта, часто з невеликим заглибленням у центрі; біла, білувата, в центрі темніша (сірувато-коричнева); поверхня гладенька, радіально-рубчаста; край рівний, тонкий, іноді хвилястий. • Пластинки: білі, рідкі, вузькі; не доходять до ніжки, утворюють навколо неї характерне кільце (коларіум). • Ніжка: 2–6 см × 0,1–0,2 см; циліндрична, темно-коричнева, чорнувата; блискуча, гладенька, щільна, волокниста; без кільця та піхви. • М’якоть: тонка, білувата; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('marasmius_epiphyllus', 'Маразмій листовий', 'Marasmius epiphyllus', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 0,5–1 см у діаметрі; дуже тонка, майже прозора, плівчаста; спочатку опукла, згодом плоско-розпростерта; біла, брудно-біла, іноді з рожевим або кремовим відтінком; поверхня гладенька, злегка рубчаста; край рівний, тонкий. • Пластинки: білуваті, рідкі, вузькі; прирослі або майже вільні. • Ніжка: 1–2 см × 0,05–0,1 см; капіляровидна, жовтувата, коричнева; гладенька, блискуча, щільна; без кільця та піхви. • М’якоть: дуже тонка, білувата; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["beech", "hornbeam", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('entoloma_clypeatum', 'Ентолома щитовидна', 'Entoloma clypeatum', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см у діаметрі; щільно-товстом’ясиста; спочатку дзвоникоподібна або опукла, згодом опукла або плоско-розпростерта, часто асиметрична, з нерівним, хвилястим або лопатевим краєм; сіра, коричнювато-сіра, брудно-біла; поверхня гладенька, суха, іноді злегка луската, часто тріщинувата. • Пластинки: білі, брудно-білі, згодом брудно-рожеві; широкі, густі; прирослі або майже вільні. • Ніжка: 5–10 см × 1–3 см; циліндрична, щільна, біла, волокниста, з підземним виростом; без кільця та піхви. • М’якоть: білий, дуже щільний; на зламі не змінюється; з приємним запахом борошна; смак приємний. • Споровий порошок: рожевий.', '{5,6}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": [], "season": ["spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('entoloma_rhodopolium', 'Ентолома рожево-сива', 'Entoloma rhodopolium', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 (11) см у діаметрі; тонком’ясиста; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта, часто з горбочком; сіра, оливкувато-сіра, жовтувато-сіра; поверхня гладенька, гола, злегка рубчаста; край рівний, тонкий, іноді хвилястий. • Пластинки: білуваті, згодом брудно-рожеві; широкі, густі; прирослі. • Ніжка: 5–10 см × 1–3 см; циліндрична, щільна, біла, згодом сірувата, волокниста; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; з запахом борошна, при підсиханні з неприємним запахом; смак м’який. • Споровий порошок: рожевий.', '{8,9}'::INT[], '{"color": ["grey", "olive"], "stem": ["no_ring"], "tree": ["beech", "oak"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('entoloma_nidorosum', 'Ентолома смердюча', 'Entoloma nidorosum', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–7 см у діаметрі; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта, іноді увігнута, зрідка з невиразним горбочком; оливкувато-сіра; поверхня гола, при підсиханні світлішає, блискуча, шовковиста; край рівний, тонкий. • Пластинки: білуваті, згодом брудно-рожеві; широкі, густі; прирослі. • Ніжка: 5–8 (9) см × 0,2–0,8 см; циліндрична, білувата; гола, вгорі борошниста, щільна, згодом з порожниною; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з дуже сильним аміачним запахом; смак м’який. • Споровий порошок: рожевий.', '{8,9,10}'::INT[], '{"color": ["grey", "olive"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('entoloma_sericeum', 'Ентолома шовковиста', 'Entoloma sericeum', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–6 см у діаметрі; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта, іноді з горбочком; темно-буро-коричнева, з віком вицвітає до сіро-коричневої; поверхня гола, при зволоженні шовковисто-блискуча, до краю радіально-рубчаста; край рівний, тонкий. • Пластинки: брудно-білі, коричнюваті, згодом бурувато-рожеві; широкі, густі; прирослі. • Ніжка: 3–7 см × 0,2–0,5 см; циліндрична, часом перекручена; коричнювато-бурувата або сірувата; штрихувата, біловолокниста, з порожниною; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з сильним запахом борошна; смак м’який. • Споровий порошок: рожевий.', '{9,10,11}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": [], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('entoloma_jubatum', 'Ентолома волохата', 'Entoloma jubatum', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–6 (8) см у діаметрі; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта, часто з горбочком; буро-коричнева; поверхня бархатиста або тонкоповстиста, злегка радіально-волокниста, з часом майже гола, вицвітає до сірої; край рівний, тонкий. • Пластинки: рожевуваті, згодом червонуваті; широкі, густі; прирослі. • Ніжка: 5–8 см × 0,4–0,7 см; циліндрична, кольору шапки; волокнисто-штрихувата, щільна, з порожниною; без кільця та піхви. • М’якоть: білуватий, тонкий; на зламі не змінюється; з сильним запахом борошна; смак м’який. • Споровий порошок: рожевий.', '{8,9,10}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('entoloma_aprile', 'Ентолома квітнева', 'Entoloma aprile', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 6 см у діаметрі; тонком’ясиста; спочатку конусовидно-дзвоникоподібна, згодом конусовидно-розпростерта, з горбочком у центрі; рудо-коричнева, згодом буро-коричнева, при підсиханні вицвітає до сірої; поверхня гола, клейкувата, згодом суха; край тонкий, рубчастий. • Пластинки: сіруваті, коричнювато-сірі, згодом сірувато- або коричнювато-червонуваті; широкі, густі; прирослі. • Ніжка: 5–7 см × 0,3–1 (1,3) см; циліндрична, з порожниною; білувато-коричнювато-сіра; волокнисто-штрихувата, часом волокнисто-шерстиста; без кільця та піхви. • М’якоть: сіруватий або буруватий, тонкий; на зламі не змінюється; зі слабким запахом борошна; смак м’який. • Споровий порошок: рожевий.', '{4,5}'::INT[], '{"color": ["brown", "russet"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["spring"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pluteus_cervinus', 'Плютей бурий', 'Pluteus cervinus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см у діаметрі; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта, часто з невеликим горбочком; коричнева, сірувато-бура; поверхня гладенька або радіально-волокниста, суха, матова; край рівний, тонкий, іноді розтрісканий. • Пластинки: вільні, білі, згодом рожеві; широкі, густі. • Ніжка: 5–10 см × 0,5–1,5 см; циліндрична, білувата; темноволокниста, щільна; без кільця та піхви. • М’якоть: білий, м’який; на зламі не змінюється; з неприємним запахом редьки; смак м’який, злегка редьковий. • Споровий порошок: рожевий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pluteus_salicinus', 'Плютей вербовий', 'Pluteus salicinus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–8 см у діаметрі; спочатку дзвоникоподібна, згодом опукла або плоско-розпростерта; сріблясто- або синювато-сіра, синювато-зеленувата; поверхня гладенька, волокниста, суха; край рівний, тонкий. • Пластинки: вільні, білуваті, згодом червонуваті; широкі, густі. • Ніжка: 3–6 см × 0,3–0,5 см; циліндрична, біла, до основи синювато-зелена; волокниста, щільна; без кільця та піхви. • М’якоть: білуватий; на зламі зеленіє; запах і смак м’які, грибні. • Споровий порошок: рожевий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["blue", "grey"], "stem": ["no_ring"], "tree": ["alder", "willow"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_eburneus', 'Гігрофор жовтувато-білий', 'Hygrophorus eburneus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–10 см у діаметрі; спочатку конусовидна, згодом опукло- або плоско-розпростерта, з підігнутим тонкоповстистим краєм; біла, білувата; поверхня дуже слизька, гола, блискуча; край рівний, тонкий. • Пластинки: білі, рідкі, товсті; низько спускаються на ніжку; прирослі. • Ніжка: 4–12 см × 0,8–1,5 см; циліндрична, щільна, біла; слизька, вгорі луската, з часом з порожниною; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; зі слабким грибним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_chrysodon', 'Гігрофор золотистий', 'Hygrophorus chrysodon', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–8 см у діаметрі; щільно-товстом’ясиста; спочатку опукла, згодом плоско-розпростерта, з горбочком; біла, до краю лимонно-жовта; поверхня волосисто-шерстиста, пластівчаста; край рівний, тонкий. • Пластинки: білі, згодом жовтуваті, рідкі, товсті; прирослі або злегка спускаються на ніжку. • Ніжка: 5–8 см × 1–1,5 см; циліндрична, щільна, біла; вгорі жовтозерниста, з кільцевидним потовщенням; без справжнього кільця. • М’якоть: білий, щільний; на зламі не змінюється; зі специфічним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["white", "yellow"], "stem": ["no_ring"], "tree": ["beech", "deciduous", "oak"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_hypothejus', 'Гігрофор пізній', 'Hygrophorus hypothejus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–6 (12) см у діаметрі; напівсферична, згодом опукло- або плоско-розпростерта; бурувато-оливкова, оливково-коричнева або рудувата; поверхня дуже слизька, гола, з віком світлішає до жовтої; край рівний, тонкий, іноді хвилястий. • Пластинки: жовтуваті, згодом оранжево-жовті, вузькі; спускаються на ніжку; прирослі. • Ніжка: 5–10 см × 0,6–1 см; циліндрична, лимонно-жовта, вгорі та біля основи біла; слизька, з кільцевидними залишками покривала; без справжнього кільця. • М’якоть: білий, під шкіркою жовтуватий; на зламі не змінюється; з приємним грибним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["brown", "olive"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_olivaceo_albus', 'Гігрофор оливково-білий', 'Hygrophorus olivaceo-albus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2,5–6 (10) см у діаметрі; тупоконусовидна, згодом опукло-розпростерта, часто з горбочком; бурувато-оливкувата або оливково-коричнювата, в центрі темніша, до краю світліша; поверхня слизька, гола; край рівний, тонкий. • Пластинки: білі, рідкі; спускаються на ніжку; прирослі. • Ніжка: 8–12 (14) см × 0,6–1,2 см; циліндрична, білувата, коричнювато-сіра; слизька, вгорі темноплівчасто-луската, з кільцевидним потовщенням, утвореним слизьким покривалом. • М’якоть: білий, під шкіркою жовтуватий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["brown", "olive"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_russula', 'Гігрофор сироїжковидний', 'Hygrophorus russula', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–20 см у діаметрі; щільно-товстом’ясиста, опукла, подушковидна, часто асиметрична; спочатку біла, згодом рожева, пурпурова, з розпливчастими плямами; поверхня слизька, луската; край рівний, іноді хвилястий. • Пластинки: дуже густі, білі, згодом червонуваті; прирослі або злегка спускаються на ніжку. • Ніжка: 3–8 см × 1–3 см; циліндрична, щільна, вгорі біла, нижче кольору шапки; волокниста; без кільця та піхви. • М’якоть: білий, щільний; на зламі в шапці майже не змінюється, в ніжці червоніє; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["pink", "purple"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_pratensis', 'Гігрофор луговий', 'Hygrophorus pratensis', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–10 см у діаметрі; щільно-товстом’ясиста, плоско-, опукло- або увігнуто-розпростерта, з горбочком; рудувато-оранжева, іноді рудувато-коричнева, з віком вицвітає; поверхня гола, гладенька, суха; край рівний, тонкий, іноді хвилястий. • Пластинки: дуже рідкі, товсті, кольору шапки, широкі; спускаються на ніжку; прирослі. • Ніжка: 4–7 (10) см × 0,6–1,8 см; циліндрична, донизу злегка потоншується; кольору шапки; гола, гладенька, щільна; без кільця та піхви. • М’якоть: світло-рудуватий, щільний; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["orange", "russet"], "stem": ["no_ring"], "tree": [], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_nemoreus', 'Гігрофор дібровний', 'Hygrophorus nemoreus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 см у діаметрі; щільно-товстом’ясиста, опукла, згодом плоско-розпростерта; рудувато-оранжева, суха, шорстка, іноді тонковолокниста, майже повстиста; край рівний, тонкий. • Пластинки: кольору шапки, товсті, низько спускаються на ніжку; прирослі. • Ніжка: 4–8 см × 1–1,8 см; циліндрична, щільна, кольору шапки; волокнисто-штрихувата; без кільця та піхви. • М’якоть: щільний, білий; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["orange", "russet"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_camarophyllus', 'Гігрофор козячий', 'Hygrophorus camarophyllus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–18 см у діаметрі; щільно-товстом’ясиста, конусовидно-, опукло- або увігнуто-розпростерта; коричнево- або буро-сіра, в центрі темніша; поверхня спочатку клейкувата, згодом суха, грубоволокниста; край рівний, тонкий. • Пластинки: білі, з часом сіруваті, рідкі, товсті, широкі; низько спускаються на ніжку. • Ніжка: 6–12 см × 1–2,5 см; циліндрична, донизу поступово звужується; кольору шапки; волокнисто-штрихувата, щільна, з підземним виростом; без кільця та піхви. • М’якоть: білий, з віком злегка буріє; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["coniferous", "mixed", "pine", "spruce"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_virgineus', 'Гігрофор дівочий', 'Hygrophorus virgineus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 (6) см у діаметрі; м’ясиста, опукло-розпростерта, з підігнутим, іноді лопатевидним краєм; біла, гола, гладенька, іноді з червонуватими розпливчастими плямами; край рівний, тонкий. • Пластинки: білі, дуже рідкі, товсті; низько спускаються на ніжку; прирослі. • Ніжка: 2–5 (6) см × 0,5–1,5 см; циліндрична, донизу звужена; біла, гола, гладенька; щільна; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_fornicatus', 'Гігрофор склепистий', 'Hygrophorus fornicatus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–6 см у діаметрі; здебільшого асиметрична, конусовидна, дзвоникоподібна, згодом розпростерта, з горбочком; біла, брудно-біла, іноді з оливковим або коричнюватим відтінком у центрі; поверхня гола, гладенька; край рівний, тонкий. • Пластинки: білі, широкоприрослі; рідкі, товсті. • Ніжка: 3–6 (8) см × 0,4–1,2 см; циліндрична, донизу звужена; кольору шапки; гладенька, щільна; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_foetens', 'Гігрофор смердючий', 'Hygrophorus foetens', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1,5–2,5 см у діаметрі; напівкуляста, згодом розпростерта; бура або темно-коричнева, при достиганні тріщинувата; суха, гола або злегка повстиста; край рівний. • Пластинки: брудно-сірі, спускаються на ніжку; рідкі. • Ніжка: 2,5–4 см × 0,3–0,4 см; циліндрична, кольору шапки; щільна; без кільця та піхви. • М’якоть: буруватий, тонкий; на зламі не змінюється; з дуже неприємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_capreolarius', 'Гігрофор винно-червоний', 'Hygrophorus capreolarius', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–8 см у діаметрі; напівкуляста, згодом опукло-розпростерта, з тупим горбочком у центрі, зрідка увігнута, з опущеним краєм; кольору вина, коричнево-пурпурова; поверхня волокниста, злегка повстиста; край рівний, тонкий. • Пластинки: кольору шапки, з прожилками, біля ніжки вилочковидно розгалужені; спускаються на ніжку. • Ніжка: 3–6 см × 0,8–2,5 см; донизу злегка потовщена; кольору шапки або світліша; сітчаста, щільна; без кільця та піхви. • М’якоть: пурпуровий, коричнювато-червоний; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: рожевувато-білий.', '{8,9,10}'::INT[], '{"color": ["purple", "red"], "stem": ["no_ring"], "tree": ["coniferous", "mixed", "pine", "spruce"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_marzuolus', 'Гігрофор ранній', 'Hygrophorus marzuolus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см у діаметрі; щільно-товстом’ясиста, опукло- або подушковидно-розпростерта, іноді асиметрична; білувата, згодом сіра, до бурувато- або чорнувато-сірої; поверхня суха, гола; край опущений, нерівний, часто хвилястий. • Пластинки: білі, білуваті, сірі, рідкі, вузькі; злегка спускаються на ніжку. • Ніжка: 3–6 см × 1,5–4 см; циліндрична, біла, білувата, сіра; вгорі борошниста, щільна, часто з порожниною, нижче волокниста; без кільця та піхви. • М’якоть: щільний, білий; на зламі згодом сіріє; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{4,5,6}'::INT[], '{"color": ["grey", "white"], "stem": ["no_ring"], "tree": ["coniferous", "pine", "spruce"], "season": ["spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_penarius', 'Гігрофор їстівний', 'Hygrophorus penarius', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: (5) 6–10 см у діаметрі; опукло-розпростерта, іноді з горбочком; щільном’ясиста; білувата, кольору шкіри, жовтувата, солом’яно-жовта, до краю світліша; поверхня спочатку клейкувата, згодом суха; край рівний, тонкий. • Пластинки: кремові, жовтуваті, дуже низько спускаються на ніжку; рідкі. • Ніжка: 3–6 см × 1,5–2 см; до середини потовщена, з кореневидним виростом; кольору шапки; тонкозерниста, щільна; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["brown", "white"], "stem": ["no_ring"], "tree": ["beech"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hygrophorus_lucorum', 'Гігрофор модриновий', 'Hygrophorus lucorum', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 см у діаметрі; б.-м. опукло-розпростерта з опущеним краєм; лимонно-жовта, по краю з залишками покривала; поверхня слизька, гола; край рівний, тонкий. • Пластинки: білуваті, згодом жовтіють, злегка спускаються на ніжку; рідкі. • Ніжка: 4–6 см × 0,7–1 см; циліндрична, білувата або світло-лимонно-жовта, з залишками кортини; біловолокниста, вгорі борошнисто-біла, щільна; без справжнього кільця. • М’якоть: білий, під шкіркою жовтий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{9,10,11}'::INT[], '{"color": ["yellow"], "stem": ["no_ring"], "tree": ["larch"], "season": ["autumn"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('coprinus_comatus', 'Гнойовик білий', 'Coprinus comatus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 см у діаметрі; циліндрична, видовжена, біла, з буруватими лусками; поверхня волокнисто-луската; край підігнутий, з часом розпливається. • Пластинки: вільні, білі → рожеві → чорні, розпливаються (автоліз); дуже густі. • Ніжка: 10–20 см × 1–2 см; циліндрична, біла, з рухомим кільцем; щільна, порожниста; з кільцем. • М’якоть: білий, м’який; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: чорний.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["white"], "stem": ["ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('coprinus_atramentarius', 'Гнойовик сірий', 'Coprinus atramentarius', 'conditionally_edible', 'Умовно їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 см у діаметрі; дзвоникоподібна, згодом розпростерта; сірувато-коричнева, з лусками; поверхня волокнисто-луската; край підігнутий, з часом розпливається. • Пластинки: білі → чорні, розпливаються (автоліз); вільні, густі. • Ніжка: 5–10 см × 0,5–1,5 см; циліндрична, біла, без кільця; щільна, порожниста. • М’якоть: білий, м’який; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: чорний.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('coprinus_micaceus', 'Гнойовик мерехтливий', 'Coprinus micaceus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 см у діаметрі; дзвоникоподібна, згодом розпростерта; жовтувато-коричнева, з блискучими зернятками; поверхня зернисто-луската; край підігнутий, з часом розпливається. • Пластинки: білі → чорні, розпливаються (автоліз); вільні, густі. • Ніжка: 3–8 см × 0,2–0,4 см; циліндрична, біла; щільна, порожниста; без кільця. • М’якоть: білий, тонкий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: чорний.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["brown", "yellow"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('coprinus_radians', 'Гнойовик променистий', 'Coprinus radians', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–3 см у діаметрі; дзвоникоподібна, згодом розпростерта; жовтувато-оранжева, з волокнистими лусками; поверхня волокнисто-луската; край підігнутий, з часом розпливається. • Пластинки: чорні, розпливаються (автоліз); вільні, густі. • Ніжка: 2–5 см × 0,2–0,3 см; циліндрична, білувата; щільна, порожниста; без кільця. • М’якоть: тонкий, білуватий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: чорний.', '{5,6,7,8,9,10}'::INT[], '{"color": ["orange", "yellow"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('coprinus_lagopus', 'Гнойовик заяча лапа', 'Coprinus lagopus', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–3 см у діаметрі; дзвоникоподібна, згодом розпростерта; білувата, з волосками; поверхня волосиста; край підігнутий, з часом розпливається. • Пластинки: чорні, розпливаються (автоліз); вільні, густі. • Ніжка: 3–8 см × 0,2–0,3 см; циліндрична, біла, волосиста; щільна, порожниста; без кільця. • М’якоть: тонкий, білуватий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: чорний.', '{5,6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hypholoma_fasciculare', 'Опеньок сірчано-жовтий', 'Hypholoma fasciculare', 'poisonous', 'Отруйний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта, часто з горбочком; сірчано-жовта, в центрі оранжево-коричнева; поверхня гладенька, гола; край рівний, тонкий. • Пластинки: сірчано-жовті → оливково-чорні; густі, прирослі. • Ніжка: 3–10 см × 0,3–0,8 см; циліндрична, сірчано-жовта, волокниста; щільна, порожниста; без кільця та піхви. • М’якоть: жовтуватий; на зламі не змінюється; з неприємним запахом; смак дуже гіркий. • Споровий порошок: оливково-чорний.', '{5,6,7,8,9,10,11}'::INT[], '{"color": ["yellow"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('hypholoma_capnoides', 'Опеньок димчастий', 'Hypholoma capnoides', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; жовтувато-коричнева, до краю світліша; поверхня гладенька, гола; край рівний, тонкий. • Пластинки: сірі → димчасто-сірі; густі, прирослі. • Ніжка: 3–8 см × 0,3–0,6 см; циліндрична, жовтувата, волокниста; щільна, порожниста; без кільця та піхви. • М’якоть: білуватий; на зламі не змінюється; з приємним запахом; смак м’який, без гіркоти. • Споровий порошок: темно-коричневий.', '{8,9,10}'::INT[], '{"color": ["brown", "yellow"], "stem": ["no_ring"], "tree": ["coniferous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('stropharia_aeruginosa', 'Строфарія синьо-зелена', 'Stropharia aeruginosa', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 см у діаметрі; спочатку напівсферична, згодом плоско-розпростерта; синьо-зелена, з білими пластівцями; поверхня слизька, гола; край рівний, тонкий, з пластівцями. • Пластинки: сірі → темно-коричневі; густі, прирослі. • Ніжка: 4–8 см × 0,5–1 см; циліндрична, синьо-зелена, з кільцем; щільна, порожниста. • М’якоть: синювато-зелений; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: темно-пурпурово-коричневий.', '{8,9,10}'::INT[], '{"color": ["blue", "green"], "stem": ["ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pholiota_squarrosa', 'Лускатка луската', 'Pholiota squarrosa', 'conditionally_edible', 'Умовно їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; жовтувато-іржава, з відстовбурченими лусками; поверхня луската; край підігнутий, з лусками. • Пластинки: жовтуваті → іржаво-коричневі; густі, прирослі. • Ніжка: 5–10 см × 1–2 см; циліндрична, з кільцем, луската; щільна, порожниста. • М’якоть: жовтуватий; на зламі не змінюється; з запахом редьки; смак м’який. • Споровий порошок: іржаво-коричневий.', '{8,9,10}'::INT[], '{"color": ["russet", "yellow"], "stem": ["ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pholiota_aurivella', 'Лускатка золотиста', 'Pholiota aurivella', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; золотисто-жовта, з іржавими лусками; поверхня луската, слизька; край підігнутий, з лусками. • Пластинки: жовтуваті → іржаво-коричневі; густі, прирослі. • Ніжка: 5–10 см × 1–2 см; циліндрична, з кільцем, луската; щільна, порожниста. • М’якоть: жовтуватий; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: іржаво-коричневий.', '{8,9,10}'::INT[], '{"color": ["yellow"], "stem": ["ring"], "tree": ["deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('cortinarius_violaceus', 'Павутинник фіолетовий', 'Cortinarius violaceus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 см у діаметрі; спочатку напівсферична, згодом плоско-розпростерта; темно-фіолетова, оксамитова; поверхня тонкоповстиста; край підігнутий, з кортиною. • Пластинки: фіолетові → іржаво-бурі; густі, прирослі. • Ніжка: 6–12 см × 1–2 см; циліндрична, фіолетова, з кортиною; щільна, порожниста; без кільця, з кортиною. • М’якоть: фіолетовий; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: іржаво-коричневий.', '{8,9,10}'::INT[], '{"color": ["purple"], "stem": ["no_ring"], "tree": ["beech", "coniferous", "deciduous", "oak", "pine"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('cortinarius_armillatus', 'Павутинник браслетний', 'Cortinarius armillatus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; іржаво-коричнева; поверхня волокниста; край підігнутий, з кортиною. • Пластинки: брудно-іржаві; густі, прирослі. • Ніжка: 6–12 см × 1–2 см; циліндрична, світло-коричнева, з цегляно-червоними кільцями (браслетами); щільна, порожниста. • М’якоть: буруватий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: іржаво-коричневий.', '{8,9,10}'::INT[], '{"color": ["brown", "russet"], "stem": ["no_ring"], "tree": ["birch", "coniferous", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('cortinarius_triumphans', 'Павутинник тріумфальний', 'Cortinarius triumphans', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см у діаметрі; спочатку напівсферична, згодом плоско-розпростерта; жовтувато-оранжева; поверхня слизька, гола; край підігнутий, з кортиною. • Пластинки: блідо-сірі → іржаво-бурі; густі, прирослі. • Ніжка: 6–12 см × 1–2 см; циліндрична, білувата, з кортиною; щільна, порожниста. • М’якоть: білий; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: іржаво-коричневий.', '{8,9,10}'::INT[], '{"color": ["orange", "yellow"], "stem": ["no_ring"], "tree": ["birch", "deciduous", "mixed"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('inocybe_rimosa', 'Волоконниця тріщинувата', 'Inocybe rimosa', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 1–3 см у діаметрі; спочатку конусовидна, згодом плоско-розпростерта, з горбочком; біла, шовковиста; поверхня гладенька, радіально-волокниста; край рівний, тонкий. • Пластинки: білі → брудно-сірі; густі, прирослі. • Ніжка: 3–6 см × 0,2–0,4 см; циліндрична, біла; щільна, порожниста; без кільця та піхви. • М’якоть: білий; на зламі не змінюється; із запахом землі; смак м’який. • Споровий порошок: брудно-коричневий.', '{7,8,9,10}'::INT[], '{"color": [], "stem": [], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('inocybe_fastigiata', 'Волоконниця рівновершинна', 'Inocybe fastigiata', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–6 см у діаметрі; спочатку конусовидна, згодом плоско-розпростерта, з горбочком; жовтувато-коричнева; поверхня радіально-волокниста; край рівний, розтрісканий. • Пластинки: білуваті → брудно-коричневі; густі, прирослі. • Ніжка: 4–8 см × 0,3–0,6 см; циліндрична, білувата; щільна, порожниста; без кільця та піхви. • М’якоть: білий; на зламі не змінюється; з неприємним запахом; смак м’який. • Споровий порошок: брудно-коричневий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "yellow"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('macrolepiota_rhacodes', 'Гриб-зонтик червоніючий', 'Macrolepiota rhacodes', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–15 см у діаметрі; спочатку яйцевидна, згодом конусовидно- або плоско-розпростерта; сірувато-коричнева, з великими лусками; поверхня луската; край рівний, з пластівцями. • Пластинки: білі → рожеві; густі, вільні. • Ніжка: 8–15 см × 1–2 см; циліндрична, білувата, з кільцем; щільна, порожниста. • М’якоть: білий; на зламі червоніє; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{7,8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lepiota_clypeolaria', 'Лепіота щитоносна', 'Lepiota clypeolaria', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–8 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; білувата, з жовтувато-коричневими лусочками; поверхня луската; край рівний, з пластівцями. • Пластинки: білі; густі, вільні. • Ніжка: 4–8 см × 0,5–1 см; циліндрична, білувата, з кільцем; щільна, порожниста. • М’якоть: білий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "white", "yellow"], "stem": ["ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lepiota_cristata', 'Лепіота гребінчаста', 'Lepiota cristata', 'poisonous', 'Отруйна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–5 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; білувата, з червонувато-коричневими лусочками; поверхня луската; край рівний, з пластівцями. • Пластинки: білі; густі, вільні. • Ніжка: 3–6 см × 0,2–0,4 см; циліндрична, білувата, з кільцем; щільна, порожниста. • М’якоть: білий; на зламі не змінюється; з неприємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "red", "white"], "stem": ["ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lepiota_felina', 'Лепіота котяча', 'Lepiota felina', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–4 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; білувата, з чорнуватими лусочками; поверхня луската; край рівний, з пластівцями. • Пластинки: білі; густі, вільні. • Ніжка: 3–5 см × 0,2–0,4 см; циліндрична, білувата, з кільцем; щільна, порожниста. • М’якоть: білий; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["black", "white"], "stem": ["ring"], "tree": ["coniferous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lepiota_lilacea', 'Лепіота лілова', 'Lepiota lilacea', 'inedible', 'Неїстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–4 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; сірувато- або червонувато-коричнева, лілувата; поверхня луската; край рівний, з пластівцями. • Пластинки: білі; густі, вільні. • Ніжка: 2–4 см × 0,2–0,4 см; циліндрична, білувата, з кільцем; щільна, порожниста. • М’якоть: рожевуватий; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "grey", "purple"], "stem": ["ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lyophyllum_decastes', 'Ліофіл груповий', 'Lyophyllum decastes', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 6–18 см у діаметрі; спочатку опукла, згодом плоско-розпростерта; коричнево-сіра, гола; поверхня гладенька, злегка волокниста; край рівний, тонкий, іноді хвилястий. • Пластинки: коричневі → жовтуваті; густі, прирослі. • Ніжка: 7–13 см × 1–3 см; циліндрична, білувата; щільна, волокниста; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lyophyllum_connatum', 'Ліофіл зрослий', 'Lyophyllum connatum', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–16 см у діаметрі; спочатку опукла, згодом плоско-розпростерта; біла, блискуча; поверхня гладенька; край рівний, тонкий. • Пластинки: білі → сірувато-кремові; густі, прирослі. • Ніжка: 4–10 см × 0,6–2 см; циліндрична, біла; щільна, волокниста; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; з приємним парфумерним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lyophyllum_ulmarium', 'Ліофіл в''язовий', 'Lyophyllum ulmarium', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 7–25 см у діаметрі; спочатку опукла, згодом плоско-розпростерта; біла, кремова, коричнювата; поверхня гладенька; край рівний, тонкий. • Пластинки: білі; густі, прирослі. • Ніжка: 5–8 см × 2–3 см; циліндрична, білувата; щільна, волокниста; без кільця та піхви. • М’якоть: білий, жорсткуватий; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown", "white"], "stem": ["no_ring"], "tree": ["elm"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lyophyllum_loricatum', 'Ліофіл панцирний', 'Lyophyllum loricatum', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–10 см у діаметрі; спочатку опукла, згодом плоско-розпростерта; каштаново-бура, чорнувата, зернисто-складчаста; поверхня складчаста; край рівний, тонкий. • Пластинки: брудно-білуваті; густі, прирослі. • Ніжка: 5–10 см × 0,1–0,15 см; циліндрична, світло-коричнювата; щільна, волокниста; без кільця та піхви. • М’якоть: крихкий, гіркуватий; на зламі не змінюється; без особливого запаху; смак гіркуватий. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["brown"], "stem": ["no_ring"], "tree": ["beech"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lyophyllum_immundum', 'Ліофіл чорніючий', 'Lyophyllum immundum', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–8 см у діаметрі; спочатку опукла, згодом плоско-розпростерта; брудно-сіра, світло-коричнева; поверхня гладенька; край рівний, тонкий. • Пластинки: білуваті, при дотику чорніють; густі, прирослі. • Ніжка: 4–10 см × 0,6–1,2 см; циліндрична, світло-сіро-коричнева; щільна, волокниста; без кільця та піхви. • М’якоть: на повітрі чорніє; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["grey"], "stem": ["no_ring"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pleurotus_cornucopiae', 'Плеврот рясний', 'Pleurotus cornucopiae', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–12 см у діаметрі; увігнуто-розпростерта, лійковидна; білувата, жовтувата, світло-вохряна; поверхня гладенька; край рівний, тонкий. • Пластинки: білі, вузькі, низько спускаються на ніжку, з анастомозами; густі. • Ніжка: коротка, ексцентрична, іноді центральна; білувата; щільна, волокниста; без кільця та піхви. • М’якоть: білуватий, щільний; на зламі не змінюється; з запахом борошна; смак м’який. • Споровий порошок: рожевуватий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["ochre", "white"], "stem": ["no_ring"], "tree": ["beech", "elm", "oak", "willow"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pleurotus_calyptratus', 'Плеврот ковпаковидний', 'Pleurotus calyptratus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 3–10 см у діаметрі; сидяча, бічна, м’ясиста; сірувато-коричнювата; поверхня гладенька, шовковиста, при зволоженні клейка; край рівний, тонкий. • Пластинки: кремово-білуваті, при підсиханні жовті; густі, низько спускаються. • Ніжка: дуже коротка або відсутня; білувата. • М’якоть: білуватий, щільний; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["brown", "grey"], "stem": ["no_ring"], "tree": ["aspen", "poplar"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pleurotus_eryngii', 'Плеврот миколайчиковий', 'Pleurotus eryngii', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–7 см у діаметрі; опукло- або увігнуто-розпростерта; жовтувато-сірувата, коричнювата; поверхня гладенька; край рівний, тонкий. • Пластинки: білуваті, сіруваті; густі, прирослі. • Ніжка: центральна, ексцентрична; біла; щільна, волокниста; без кільця та піхви. • М’якоть: білий, щільний; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["grey", "yellow"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lentinus_tigrinus', 'Лентин тигровий', 'Lentinus tigrinus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 4–10 см у діаметрі; б.-м. лійковидна; сірувато- або вохряно-біла, згодом світлішає; поверхня волокниста, вкрита темно-коричневими лусками; край рівний, тонкий. • Пластинки: білі → жовті; густі, прирослі. • Ніжка: 3–6 см × 0,3–1,8 см; ексцентрична або центральна, донизу звужена; пружна, з кільцем, що швидко зникає, дрібно-темнолуската. • М’якоть: білий, щільний; на зламі не змінюється; зі слабким приємним запахом; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["grey", "ochre"], "stem": ["ring"], "tree": ["poplar", "willow"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lentinus_cyathiformis', 'Лентин бокаловидний', 'Lentinus cyathiformis', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: (5) 10–20 см у діаметрі; товсто-щільном’ясиста, плоско- або увігнуто-розпростерта, іноді асиметрична; кремова, жовтувата, світло-вохряно-червонувата; поверхня тонколуската; край рівний, тонкий. • Пластинки: кремові, вузькі, дуже низько спускаються на ніжку; густі, часто вилочковидно розгалужені. • Ніжка: до 15 см завдовжки, до 1,5 см завтовшки; центральна або ексцентрична; вгорі білобородавчаста, внизу червонуватопластівчаста; щільна. • М’якоть: білий, щільний, еластичний; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: білий.', '{8,9,10}'::INT[], '{"color": ["ochre", "white"], "stem": ["no_ring"], "tree": ["deciduous", "poplar", "willow"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('lentinus_lepideus', 'Лентин лускатий', 'Lentinus lepideus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 5–12 см у діаметрі; опукло-, плоско- або увігнуто-розпростерта; жовтувата, блідо-вохряно-кремова, кольору шкіри; поверхня крупно-коричнево-луската; край рівний, тонкий. • Пластинки: лимонно-жовтуваті, з часом брудно-жовті; густі, прирослі. • Ніжка: 4–6 см × 2 см; центральна, ексцентрична; з кільцем, що швидко зникає, луската; щільна. • М’якоть: білий, дуже щільний; на зламі не змінюється; з приємним запахом; смак м’який. • Споровий порошок: білий.', '{6,7,8,9,10,11}'::INT[], '{"color": ["ochre", "white", "yellow"], "stem": ["ring"], "tree": ["coniferous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('schizophyllum_commune', 'Схізофіл звичайний', 'Schizophyllum commune', 'inedible', 'Неїстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 2–4 см у діаметрі; сидяча, віяловидна, черепашковидна; сірувато-біла, волосисто-повстиста; поверхня повстиста; край рівний, хвилястий, з поздовжньо розщепленими пластинками. • Пластинки: віяловидні, рожевуваті, з розщепленим краєм; рідкі. • Ніжка: відсутня. • М’якоть: тонка, шкіряста; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: кремово-рожевий.', '{8,9,10,11}'::INT[], '{"color": ["grey", "white"], "stem": ["no_ring"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('volvariella_speciosa', 'Вольварієла прекрасна', 'Volvariella speciosa', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 10–12 см у діаметрі; спочатку яйцевидна, згодом дзвоникоподібна або плоско-розпростерта; брудно-біла, в центрі темніша; поверхня гладенька; край рівний, тонкий. • Пластинки: рожеві; густі, вільні. • Ніжка: 15–20 см × 2 см; циліндрична, біла, біля основи з білою піхвою; щільна, волокниста. • М’якоть: білий, м’який; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: рожевий.', '{6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring", "volva"], "tree": [], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('volvariella_bombycina', 'Вольварієла надеревна', 'Volvariella bombycina', 'edible', 'Їстівна', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 10–20 см у діаметрі; спочатку яйцевидна, згодом дзвоникоподібна; біла, волокнисто-луската; поверхня волокнисто-луската; край рівний, тонкий. • Пластинки: рожеві; густі, вільні. • Ніжка: 15 см завдовжки; циліндрична, біла, з широкою піхвою; щільна, волокниста. • М’якоть: білий, м’який; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: рожевий.', '{6,7,8,9,10}'::INT[], '{"color": ["white"], "stem": ["no_ring", "volva"], "tree": ["coniferous", "deciduous"], "season": ["autumn", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mushroom_catalog (id, name_ua, name_lat, edibility, edibility_label, red_listed, rarity, has_photo, top20, popular, ai_recognition, features, months, attrs, photos, peak_months, zones, license, red_book_source) VALUES ('pluteus_atromarginatus', 'Плютей чорнооторочений', 'Pluteus atromarginatus', 'edible', 'Їстівний', FALSE, '', FALSE, FALSE, FALSE, FALSE, '• Шапка: 6–8 см у діаметрі; спочатку дзвоникоподібна, згодом плоско-розпростерта; коричнева, фіолетово-коричнева, темнолуската; поверхня луската; край рівний, тонкий. • Пластинки: червонуваті, з темним краєм; густі, вільні. • Ніжка: 5–7 см × 0,7–1 см; циліндрична, кольору шапки, темно-волокнистолуската; щільна, волокниста. • М’якоть: білий, м’який; на зламі не змінюється; без особливого запаху; смак м’який. • Споровий порошок: рожевий.', '{5,6,7,8,9,10}'::INT[], '{"color": ["brown", "purple"], "stem": ["no_ring"], "tree": ["pine"], "season": ["autumn", "spring", "summer"]}'::jsonb, '[]'::jsonb, '{}'::INT[], '{}'::TEXT[], NULL, NULL) ON CONFLICT (id) DO NOTHING;
